tool_input.command:
$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$cfg=(Get-Item "C:\Users\Administrator\.dsh\profiles\web\cordis.patch.yml").LastWriteTime
Write-Host "config mtime: $cfg"
Write-Host "now: $(Get-Date)"
Write-Host "=== DSH process start ==="
Get-CimInstance Win32_Process -Filter "Name='node.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -match 'dsh' } | ForEach-Object {
  $c=$_.CommandLine; if($c.Length -gt 70){$c=$c.Substring(0,70)}
  "{0} start={1}" -f $_.ProcessId,$_.CreationDate
}
Write-Host "=== newest 6 sessions ==="
Get-ChildItem $dir -Filter "session-*.json" | Sort-Object LastWriteTime -Descending | Select-Object -First 6 | ForEach-Object {
  try{
    $j=Get-Content $_.FullName -Raw|ConvertFrom-Json
    $hs=$j.record.rows.contextHeaders.val.headers
    if(-not $hs){return}
    $names=@($hs[0].tools|ForEach-Object{$_.name})
    $bt=$j.record.rows.contextBreakdown.val.breakdown
    $sc=@($names|Where-Object{$_ -like 'schedule_*'}).Count
    $gl=@($names|Where-Object{$_ -in 'create_goal','update_goal','get_goal'}).Count
    "{0} {1:HH:mm:ss} toolCount={2} toolsTok={3} schedule_*={4} goalTools={5}" -f $_.Name.Substring(8,8),$_.LastWriteTime,$names.Count,$bt.toolsTokens,$sc,$gl
  }catch{}
}

# Sanity: confirm this current conversation is NOT fresh either (started turn1 long ago) - and confirm no live NEW session with reduced tools exists yet
$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$newWithReduced = 0
foreach($f in (Get-ChildItem $dir -Filter "session-*.json")){
  try{
    $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
    $hs=$j.record.rows.contextHeaders.val.headers
    if(-not $hs){continue}
    $names=@($hs[0].tools|ForEach-Object{$_.name})
    if($names.Count -gt 0 -and ($names -notcontains 'schedule_create') -and ($names -contains 'pwsh')){
      $newWithReduced++; Write-Host "reduced-toolset session: $($f.Name.Substring(8,8)) mtime=$($f.LastWriteTime) toolCount=$($names.Count)"
    }
  }catch{}
}
Write-Host "sessions with reduced (no schedule_create, has pwsh): $newWithReduced"
Write-Host "(expect 0 until a fresh conversation is started post-restart)"

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
# find newest session and check toolset
$latest = Get-ChildItem $dir -Filter "session-*.json" | Sort-Object LastWriteTime -Descending | Select-Object -First 3
foreach($f in $latest){
  try{
    $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
    $hs=$j.record.rows.contextHeaders.val.headers
    $steps=$j.record.rows.sessionStats.val.steps
    $title=$j.record.rows.title.val
    if(-not $hs){ Write-Host "$($f.Name.Substring(8,8)) $($f.LastWriteTime.ToString('HH:mm:ss')) steps=$steps (no headers) title=$title"; continue }
    $names=@($hs[0].tools|ForEach-Object{$_.name})
    $bt=$j.record.rows.contextBreakdown.val.breakdown
    $sc=@($names|Where-Object{$_ -like 'schedule_*'}).Count
    $gl=@($names|Where-Object{$_ -in 'create_goal','update_goal','get_goal'}).Count
    Write-Host ("{0} {1:HH:mm:ss} steps={2} toolCount={3} toolsTok={4} schedule_*={5} goalTools={6} title={7}" -f $f.Name.Substring(8,8),$f.LastWriteTime,$steps,$names.Count,$bt.toolsTokens,$sc,$gl,$title)
  }catch{ Write-Host "err $_" }
}

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
# Get removed tools token sizes from a same-model (auto/deepseek-v4.1-flash / deepseek-v4.1-flash) old standard header
$cand = Get-ChildItem $dir -Filter "session-*.json" | Where-Object {
  try{ $jj=Get-Content $_.FullName -Raw|ConvertFrom-Json
    $m=$jj.record.rows.modelSelection.val.lastUsed; $hs=$jj.record.rows.contextHeaders.val.headers
    ($m.model -like '*deepseek-v4.1-flash*' -and $hs -and (@($hs[0].tools|ForEach-Object{$_.name}) -contains 'schedule_create'))
  }catch{$false}
} | Select-Object -First 3
foreach($c in $cand){
  $cj=Get-Content $c.FullName -Raw|ConvertFrom-Json
  $tk=$cj.record.rows.contextHeaders.val.headers[0].tools
  $rem=@('create_goal','get_goal','update_goal','schedule_create','schedule_edit','schedule_list','schedule_view')
  $s=0; foreach($r in $rem){ $s+= ($tk|Where-Object{$_.name -eq $r}).tokens }
  $tb=$cj.record.rows.contextBreakdown.val.breakdown.toolsTokens
  Write-Host ("{0} model={1} totalToolsTok={2} removed7Sum={3}" -f $c.Name.Substring(8,8),$cj.record.rows.modelSelection.val.lastUsed.model,$tb,$s)
}
